#!/usr/bin/env python3
import json
import os
import shutil
import subprocess
import sys
from pathlib import Path


def load_payload() -> dict:
    raw = sys.stdin.read().strip()
    if not raw:
        return {}
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        return {}


def find_pre_commit_command() -> list[str] | None:
    executable = shutil.which("pre-commit")
    if executable:
        return [executable]
    python_executable = shutil.which("python3")
    if python_executable:
        return [python_executable, "-m", "pre_commit"]
    return None


def resolve_repo_root(payload: dict) -> Path:
    cwd = Path(payload.get("cwd") or os.getcwd())
    result = subprocess.run(
        ["git", "rev-parse", "--show-toplevel"],
        cwd=cwd,
        capture_output=True,
        text=True,
    )
    if result.returncode == 0:
        return Path(result.stdout.strip())
    return cwd


def main() -> int:
    payload = load_payload()
    repo_root = resolve_repo_root(payload)
    command = find_pre_commit_command()

    if command is None:
        print(
            json.dumps(
                {
                    "continue": false,
                    "stopReason": "pre-commit is not installed",
                    "systemMessage": (
                        "Stop hook could not find `pre-commit`. Install it, then stop the turn again."
                    ),
                }
            )
        )
        return 0

    result = subprocess.run(
        [*command, "run", "--all-files"],
        cwd=repo_root,
        capture_output=True,
        text=True,
    )

    if result.stdout:
        sys.stderr.write(result.stdout)
    if result.stderr:
        sys.stderr.write(result.stderr)

    if result.returncode == 0:
        return 0

    if payload.get("stop_hook_active"):
        print(
            json.dumps(
                {
                    "continue": false,
                    "stopReason": "pre-commit checks are still failing",
                    "systemMessage": (
                        "The Stop hook reran pre-commit and it is still failing. Review the hook output and fix the reported issues."
                    ),
                }
            )
        )
        return 0

    print(
        json.dumps(
            {
                "decision": "block",
                "reason": (
                    "Run and fix the failing pre-commit checks shown by the Stop hook, then finish the turn again."
                ),
            }
        )
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

